#define GOT_BBS_BG_H_

// BBS Info screen background art (320x192, one real-palette index byte per pixel, row-major --
// same "chunky" layout got_title_bg.h's own kMainMenuBg already uses, see that file's own comment).
// Matt: "let's add in the missing 'BBS' screen that appears when the player selects the 'BBS'
// option in the main menu... should be able to create a screen like this with our existing assets
// like how we did for the main menu" -- generated the exact same way kMainMenuBg was: downsampled
// (Lanczos, then nearest-matched with no dithering) from Matt's own real reference screenshot of
// the real GOT.EXE "BBS Info" screen straight to this port's own real PALETTE resource -- so the
// wood/rope border, red/yellow/green/cyan text, and the horizontal divider line all land on the
// exact same real palette indices this screen's reference art actually used, not an approximation.
//
// Unlike kMainMenuBg, this screen's own text is baked directly into the raster rather than drawn
// live with got_xprint() over an erased backdrop -- deliberately: the main menu needs live text
// because it has a moving cursor and highlighted selection to composite on top of it every frame
// (see that file's own comment), but this screen has neither -- it's a single static,
// non-interactive page, so there is nothing that ever needs to redraw over or recolor any part of
// it, and baking the whole thing (border AND text) preserves the reference's own exact multi-color
// line-by-line layout (e.g. "hottest" in red mid-line) pixel-for-pixel, which reconstructing via
// got_xprint() calls would only approximate. Indices 0 and 15 (modex_draw_sprite_frame()'s
// hardcoded transparent values) are deliberately avoided during generation, same precaution
// kMainMenuBg's own comment describes -- not strictly required here either, since
// got_title_draw_bbs_info() presents this the same unconditional-copy way (xcopys2d(), see that
// function's own comment), but kept anyway for consistency and in case that ever changes.
